const Prefetcher=function(){const e=new Set;function t(t){if(!t||e.has(t)||!t.startsWith(window.location.origin))return;if(t===window.location.href.split("#")[0])return;const n=document.createElement("link");n.rel="prefetch",n.href=t,document.head.appendChild(n),e.add(t)}return{init:function(){if(!("IntersectionObserver"in window))return;const e=new IntersectionObserver(n=>{n.forEach(n=>{if(n.isIntersecting){t(n.target.href),e.unobserve(n.target)}})},{rootMargin:"50px"});document.querySelectorAll("a[href]").forEach(n=>{const r=n.href;r.startsWith(window.location.origin)&&!r.includes("#")&&(e.observe(n),n.addEventListener("mouseenter",()=>t(r),{once:!0}),n.addEventListener("touchstart",()=>t(r),{once:!0}))})}}}();document.addEventListener("DOMContentLoaded",Prefetcher.init);